import{_ as a,o,c as i,ae as r}from"./chunks/framework.BmsPYn1i.js";const _=JSON.parse('{"title":"3Dの表示形式","description":"","frontmatter":{},"headers":[],"relativePath":"FeaturesIntroduction/View/index.md","filePath":"FeaturesIntroduction/View/index.md"}'),l={name:"FeaturesIntroduction/View/index.md"};function t(c,e,d,n,s,h){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_3dの表示形式" tabindex="-1">3Dの表示形式 <a class="header-anchor" href="#_3dの表示形式" aria-label="Permalink to &quot;3Dの表示形式&quot;">​</a></h1><p>a3jsで3Dを表示するクラスを「View」と呼びます。Viewには用途に 応じて以下の5種類があります。</p><ul><li><a href="./Window.html">Windowクラス</a> — タイトルバー付きの浮動ウィンドウ。 <code>new</code>するだけで表示されるので一番手軽です。</li><li><a href="./Canvas.html">Canvasクラス</a> — 自分でページに配置するHTML要素。 CSSで自由にデザインできます。</li><li><a href="./GameCanvas.html">GameCanvasクラス</a> — ジョイスティックUI付きの ゲーム向けView。スマホでもPCでも操作できます。</li><li><a href="./VRView.html">VRViewクラス</a> — ヘッドマウントディスプレイ(HMD)での VR表示用のView。</li><li><a href="./ARView.html">ARViewクラス</a> — スマートフォンなどでのAR表示用のView。</li></ul><h2 id="viewの共通機能" tabindex="-1">Viewの共通機能 <a class="header-anchor" href="#viewの共通機能" aria-label="Permalink to &quot;Viewの共通機能&quot;">​</a></h2><p>どのViewも共通の<code>View</code>インターフェースを実装しており、生成した 直後から表示できる状態で作られます。内部に以下のものを持っています。</p><ul><li><code>view.scene</code> — 表示するオブジェクトを追加するシーン。</li><li><code>view.camera</code> — シーンを映すカメラ。初期位置は<code>(0, 0, 3)</code>で、 ヘッドライトがついています。</li><li><code>view.controller</code> — 入力を処理するコントローラー。デフォルトは マウスやタッチで視点を回転できる<code>OrbitController</code>です。</li></ul><p>共通のメソッドとして以下のものがあります。</p><ul><li><code>replaceScene(newScene)</code> — 表示するシーンを切り替えます。 スタート画面とゲーム画面の切り替えなどに使います。詳しくは <a href="./../Scene/">Sceneの使用方法</a>を参照してください。</li><li><code>setController(controller)</code> — コントローラーを切り替えます。 詳しくは<a href="./../Controller/">Controllerについて</a>を参照してください。</li><li><code>waitForRender()</code> — 次のフレームが描画されるまで待ちます。 ループと組み合わせてアニメーションを作るのに使います。</li><li><code>setShadowMap(true)</code> — 影の描画を有効にします。詳しくは <a href="./../Shadow/">影を表示する方法</a>を参照してください。</li><li><code>worldToScreen()</code>・<code>screenToWorld()</code>・<code>cameraToScreen()</code>・ <code>screenToCamera()</code> — ワールド座標・カメラ座標と画面上の ピクセル座標を相互に変換します。</li></ul><p>詳細は<a href="https://kenji0717.github.io/a3js/api/interfaces/View.html" target="_blank" rel="noreferrer">APIドキュメント</a>を 参照してください。</p>',9)])])}const p=a(l,[["render",t]]);export{_ as __pageData,p as default};
